def _uid(user):
    return str(user['id'])


def _attempts(user):
    uid=quote(_uid(user),safe='')
    return _request('GET', '/rest/v1/grammar_practice_attempts?select=topic,correct,total,completed_at&user_id=eq.'+uid+'&order=completed_at.desc&limit=100',service=True) or []


def _save(user, topic, score, total, session_key):
    # Idempotency key avoids duplicate saves on Streamlit reruns.
    _request('POST','/rest/v1/rpc/save_grammar_attempt',service=True,payload={
        'p_user_id':_uid(user),'p_topic':topic,'p_correct':score,'p_total':total,'p_attempt_key':session_key})


def render_grammar_lab(user):
    with st.expander('🧩 Sanskrit Grammar Practice Lab', expanded=False):
        st.caption('Practice cases, verb forms, Sandhi and compounds. Curated beginner exercises; no OpenAI tokens are used.')
        try:
            records=_attempts(user)
            if records:
                total=sum(int(r.get('total') or 0) for r in records)
                correct=sum(int(r.get('correct') or 0) for r in records)
                a,b,c=st.columns(3)
                a.metric('Practice sessions',len(records))
                b.metric('Questions answered',total)
                c.metric('Accuracy',f'{correct/total:.0%}' if total else '—')
        except (BetaError, ValueError, TypeError) as exc:
            st.warning('Grammar progress is unavailable. Run grammar_lab_setup.sql in Supabase before practicing.')
            st.caption(str(exc))
            return
        topic=st.selectbox('Choose a grammar topic',list(BANK),key='grammar_lab_topic')
        lesson_id=hashlib.sha256((str(user['id'])+'|'+topic).encode()).hexdigest()[:12]
        state_key='grammar_lab_'+lesson_id
        if state_key not in st.session_state:
            st.session_state[state_key]={'answers':{},'saved':False,'attempt_key':None}
        state=st.session_state[state_key]
        questions=BANK[topic]
        st.progress(len(state['answers'])/len(questions))
        st.caption(f"{len(state['answers'])} of {len(questions)} questions answered")
        for i,(question,options,correct,explanation) in enumerate(questions):
            with st.container(border=True):
                st.markdown(f'**Question {i+1}. {question}**')
                if i in state['answers']:
                    chosen=state['answers'][i]
                    st.write('Your answer: '+options[chosen])
                    if chosen==correct:
                        st.success('Correct! '+explanation)
                    else:
                        st.error('Not quite. '+explanation)
                        st.info('Correct answer: '+options[correct])
                else:
                    choice=st.radio('Select an answer',options,index=None,key=f'grammar_choice_{lesson_id}_{i}',label_visibility='collapsed')
                    if st.button('Check answer',key=f'grammar_check_{lesson_id}_{i}',disabled=choice is None,use_container_width=True):
                        state['answers'][i]=options.index(choice)
                        st.rerun()
        if len(state['answers'])==len(questions):
            score=sum(state['answers'][i]==q[2] for i,q in enumerate(questions))
            st.success(f'Practice complete! Your score: {score} / {len(questions)}')
            if state['attempt_key'] is None:
                import uuid
                state['attempt_key']=str(uuid.uuid4())
            if not state['saved']:
                try:
                    _save(user,topic,score,len(questions),state['attempt_key'])
                    state['saved']=True
                except (BetaError, ValueError, TypeError) as exc:
                    st.error('Could not save grammar progress. Your answers remain in this browser session.')
                    st.caption(str(exc))
                    if st.button('Retry saving progress',key='grammar_retry_'+lesson_id):
                        st.rerun()
                else:
                    st.success('Progress saved to your Supabase account.')
            else:
                st.caption('Progress saved to your Supabase account.')
            if st.button('↻ Practice this topic again',key='grammar_reset_'+lesson_id):
                st.session_state[state_key]={'answers':{},'saved':False,'attempt_key':None}
                for i in range(len(questions)):
                    st.session_state.pop(f'grammar_choice_{lesson_id}_{i}',None)
                st.rerun()
        st.caption('Exercises use standard introductory Sanskrit examples. Advanced or context-dependent grammatical interpretations may differ.')
